 public override void OnInspectorGUI(){EditorGUI.BeginDisabledGroup(Application.isPlaying);DrawDefaultInspector();if(GUILayout.Button("Open spatial editing for this skill")){if(!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()){EditorGUI.EndDisabledGroup();return;}EditorSceneManager.OpenScene("Assets/Shioka/Development/Scenes/MoveSpatialAuthoring.unity");var a=UnityEngine.Object.FindAnyObjectByType<TrainingSpatialAuthoring>();if(a!=null){var data=(TrainingMoveData)target;a.command=data.data.command;a.action=a.command==TrainingCommand.AirStrongPunch||a.command==TrainingCommand.AirStrongKick||a.command==TrainingCommand.AirDownStrongKick||a.command==TrainingCommand.AirSpecial2?TrainingSpatialAuthoring.ActionKind.Air:TrainingSpatialAuthoring.ActionKind.Ground;a.Reload();Selection.activeGameObject=a.gameObject;}}EditorGUI.EndDisabledGroup();EditorGUILayout.HelpBox("Source skill data. Play uses detached runtime values. Spatial Save writes this same skill owner, not a duplicate catalog copy.",MessageType.Info);}
